    // -- #1595 / #1598 — resilient-backfill + reembed storage helpers --

    /// #1595 — the keyset fetch pages strictly past the cursor in `id`
    /// order, and rows that gain an embedding drop out of the scan.
    #[test]
    fn unembedded_batch_after_cursor_paginates_1595() {
        let conn = test_db();
        let mut ids: Vec<String> = (0..5)
            .map(|i| {
                insert(
                    &conn,
                    &make_memory(&format!("row-{i}"), "bf-1595", Tier::Long, 5),
                )
                .unwrap()
            })
            .collect();
        ids.sort();

        let first = get_unembedded_ids_batch_after(&conn, None, 2).unwrap();
        assert_eq!(first.rows.len(), 2);
        assert_eq!(first.rows[0].0, ids[0], "scan starts at the smallest id");
        // #2336 — the raw cursor equals the last resolved id when nothing
        // was decrypt-skipped.
        assert_eq!(
            first.raw_last_id.as_deref(),
            Some(first.rows.last().unwrap().0.as_str())
        );
        assert_eq!(first.decrypt_skipped, 0);
        let cursor = first.rows.last().unwrap().0.clone();

        let rest = get_unembedded_ids_batch_after(&conn, Some(&cursor), 10).unwrap();
        assert_eq!(rest.rows.len(), 3);
        assert!(
            rest.rows
                .iter()
                .all(|(id, _, _)| id.as_str() > cursor.as_str()),
            "every row must sort strictly after the cursor"
        );

        // Embedded rows leave the unembedded predicate.
        set_embedding(
            &conn,
            &ids[0],
            &[0.1, 0.2],
            &crate::embeddings::embedding_space_fingerprint("test-space"),
        )
        .unwrap();
        let after = get_unembedded_ids_batch_after(&conn, None, 10).unwrap();
        assert_eq!(after.rows.len(), 4);
        assert!(after.rows.iter().all(|(id, _, _)| id != &ids[0]));
    }

    /// #1598 — the reembed full-corpus scan returns embedded AND
    /// unembedded rows, honors the namespace filter, and pages by
    /// cursor.
    #[test]
    fn memory_texts_batch_namespace_and_cursor_1598() {
        let conn = test_db();
        let mut ns_a_ids: Vec<String> = (0..3)
            .map(|i| {
                insert(
                    &conn,
                    &make_memory(&format!("a-{i}"), "reembed-a", Tier::Long, 5),
                )
                .unwrap()
            })
            .collect();
        ns_a_ids.sort();
        for i in 0..2 {
            insert(
                &conn,
                &make_memory(&format!("b-{i}"), "reembed-b", Tier::Long, 5),
            )
            .unwrap();
        }
        // An already-embedded row MUST still be scanned — reembed
        // replaces existing vectors, it is not a backfill.
        set_embedding(
            &conn,
            &ns_a_ids[0],
            &[0.5, 0.5],
            &crate::embeddings::embedding_space_fingerprint("test-space"),
        )
        .unwrap();

        let all = get_memory_texts_batch(&conn, None, None, 100, None).unwrap();
        assert_eq!(all.rows.len(), 5, "unfiltered scan sees every live row");

        let ns_a = get_memory_texts_batch(&conn, Some("reembed-a"), None, 100, None).unwrap();
        assert_eq!(ns_a.rows.len(), 3);
        assert_eq!(ns_a.rows[0].0, ns_a_ids[0], "embedded row still scanned");

        let first = get_memory_texts_batch(&conn, Some("reembed-a"), None, 1, None).unwrap();
        let cursor = first.rows[0].0.clone();
        let rest =
            get_memory_texts_batch(&conn, Some("reembed-a"), Some(&cursor), 100, None).unwrap();
        assert_eq!(rest.rows.len(), 2);
        assert!(
            rest.rows
                .iter()
                .all(|(id, _, _)| id.as_str() > cursor.as_str())
        );
    }

    /// #1598 — the reembed writer REPLACES vectors across a dim change
    /// that the checked writer (G4 invariant) refuses, and skips
    /// unknown ids like its checked sibling.
    #[test]
    fn set_embeddings_batch_reembed_bypasses_dim_invariant_1598() {
        let mut conn = test_db();
        let id1 = insert(&conn, &make_memory("dim-est", "reembed-dim", Tier::Long, 5)).unwrap();
        let id2 = insert(&conn, &make_memory("dim-mig", "reembed-dim", Tier::Long, 5)).unwrap();
        // Establish a 4-dim namespace.
        set_embedding(
            &conn,
            &id1,
            &[0.1, 0.2, 0.3, 0.4],
            &crate::embeddings::embedding_space_fingerprint("test-space"),
        )
        .unwrap();

        // The checked writer enforces the established dim…
        let refused = set_embeddings_batch(
            &mut conn,
            &[(id2.clone(), vec![0.1_f32; 8])],
            &crate::embeddings::embedding_space_fingerprint("test-space"),
        )
        .unwrap_err();
        assert!(
            refused.downcast_ref::<EmbeddingDimMismatch>().is_some(),
            "checked writer must refuse the dim change: {refused}"
        );

        // …the migration writer replaces every row to the new dim.
        let entries = vec![
            (id1.clone(), vec![0.9_f32; 8]),
            (id2.clone(), vec![0.8_f32; 8]),
        ];
        let written = set_embeddings_batch_reembed(
            &mut conn,
            &entries,
            &crate::embeddings::embedding_space_fingerprint("test-space"),
        )
        .unwrap();
        assert_eq!(written, 2);
        assert_eq!(get_embedding(&conn, &id1).unwrap().unwrap().len(), 8);
        assert_eq!(get_embedding(&conn, &id2).unwrap().unwrap().len(), 8);
        assert_eq!(
            namespace_embedding_dim(&conn, "reembed-dim").unwrap(),
            Some(8),
            "namespace converges to the target dim"
        );

        // Unknown ids are skipped; empty input is a no-op.
        let n = set_embeddings_batch_reembed(
            &mut conn,
            &[("no-such-id".to_string(), vec![0.1_f32; 8])],
            &crate::embeddings::embedding_space_fingerprint("test-space"),
        )
        .unwrap();
        assert_eq!(n, 0);
        assert_eq!(
            set_embeddings_batch_reembed(
                &mut conn,
                &[],
                &crate::embeddings::embedding_space_fingerprint("test-space")
            )
            .unwrap(),
            0
        );
    }

    // -----------------------------------------------------------------
    // v0.8.0 #1709/#1720 WS-B B2 — `reown` (rewrite metadata.agent_id).
    // -----------------------------------------------------------------

    /// Insert a row with explicit metadata so the reown tests can seed
    /// owned / unowned / multi-key shapes.
    fn insert_with_meta(
        conn: &Connection,
        title: &str,
        ns: &str,
        meta: serde_json::Value,
    ) -> String {
        let mut m = make_memory(title, ns, Tier::Long, 5);
        m.metadata = meta;
        insert(conn, &m).unwrap()
    }

    fn agent_id_of(conn: &Connection, id: &str) -> Option<String> {
        get(conn, id)
            .unwrap()
            .unwrap()
            .metadata
            .get("agent_id")
            .and_then(|v| v.as_str())
            .map(str::to_string)
    }

    /// Default reown rewrites every OWNED row's agent_id to `--to`,
    /// preserves the other metadata keys, leaves unowned rows + other
    /// namespaces untouched, and the `agent_id_idx` reflects the owner.
    #[test]
    fn reown_rewrites_owned_rows_preserving_other_keys_b2() {
        let conn = test_db();
        let owned = insert_with_meta(
            &conn,
            "owned",
            "claim-ns",
            serde_json::json!({"agent_id": "alice", "scope": "private", "k": "v"}),
        );
        let other_ns = insert_with_meta(
            &conn,
            "elsewhere",
            "other-ns",
            serde_json::json!({"agent_id": "alice"}),
        );

        let report = reown(&conn, "claim-ns", "bob", false, false).unwrap();
        assert_eq!(report.matched, 1);
        assert_eq!(report.rewritten, 1);
        assert!(!report.dry_run);

        // Owner rewritten; sibling metadata keys preserved.
        assert_eq!(agent_id_of(&conn, &owned).as_deref(), Some("bob"));
        let meta = get(&conn, &owned).unwrap().unwrap().metadata;
        assert_eq!(meta.get("scope").and_then(|v| v.as_str()), Some("private"));
        assert_eq!(meta.get("k").and_then(|v| v.as_str()), Some("v"));

        // Generated agent_id_idx re-projects the new owner.
        let idx: Option<String> = conn
            .query_row(
                "SELECT agent_id_idx FROM memories WHERE id = ?1",
                params![owned],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(idx.as_deref(), Some("bob"));

        // Other namespace untouched.
        assert_eq!(agent_id_of(&conn, &other_ns).as_deref(), Some("alice"));
    }

    /// dry-run COUNTS matched rows but writes NOTHING.
    #[test]
    fn reown_dry_run_counts_but_does_not_write_b2() {
        let conn = test_db();
        let owned = insert_with_meta(
            &conn,
            "owned",
            "claim-ns",
            serde_json::json!({"agent_id": "alice"}),
        );
        let report = reown(&conn, "claim-ns", "bob", false, true).unwrap();
        assert_eq!(report.matched, 1);
        assert_eq!(report.rewritten, 0);
        assert!(report.dry_run);
        // No write happened.
        assert_eq!(agent_id_of(&conn, &owned).as_deref(), Some("alice"));
    }

    /// `--claim-unowned` covers empty/missing-agent_id rows; the default
    /// leaves them untouched.
    #[test]
    fn reown_claim_unowned_covers_empty_and_missing_b2() {
        let conn = test_db();
        let owned = insert_with_meta(
            &conn,
            "owned",
            "claim-ns",
            serde_json::json!({"agent_id": "alice"}),
        );
        let empty = insert_with_meta(
            &conn,
            "empty",
            "claim-ns",
            serde_json::json!({"agent_id": ""}),
        );
        let missing = insert_with_meta(
            &conn,
            "missing",
            "claim-ns",
            serde_json::json!({"scope": "private"}),
        );

        // Default leaves the unowned rows alone (matches only `owned`).
        let default_report = reown(&conn, "claim-ns", "bob", false, true).unwrap();
        assert_eq!(default_report.matched, 1);

        // claim_unowned covers all three.
        let report = reown(&conn, "claim-ns", "bob", true, false).unwrap();
        assert_eq!(report.matched, 3);
        assert_eq!(report.rewritten, 3);
        assert_eq!(agent_id_of(&conn, &owned).as_deref(), Some("bob"));
        assert_eq!(agent_id_of(&conn, &empty).as_deref(), Some("bob"));
        assert_eq!(agent_id_of(&conn, &missing).as_deref(), Some("bob"));
        // The previously-missing row had its other keys preserved.
        let meta = get(&conn, &missing).unwrap().unwrap().metadata;
        assert_eq!(meta.get("scope").and_then(|v| v.as_str()), Some("private"));
    }

    /// Running reown twice is idempotent (second run rewrites the same
    /// rows to the same id, no error, same count).
    #[test]
    fn reown_is_idempotent_b2() {
        let conn = test_db();
        let owned = insert_with_meta(
            &conn,
            "owned",
            "claim-ns",
            serde_json::json!({"agent_id": "alice"}),
        );
        let first = reown(&conn, "claim-ns", "bob", false, false).unwrap();
        let second = reown(&conn, "claim-ns", "bob", false, false).unwrap();
        assert_eq!(first.rewritten, 1);
        assert_eq!(second.matched, 1);
        assert_eq!(second.rewritten, 1);
        assert_eq!(agent_id_of(&conn, &owned).as_deref(), Some("bob"));
    }

    /// A malformed `--to` agent_id is rejected before any write.
    #[test]
    fn reown_rejects_invalid_to_id_b2() {
        let conn = test_db();
        let owned = insert_with_meta(
            &conn,
            "owned",
            "claim-ns",
            serde_json::json!({"agent_id": "alice"}),
        );
        // Whitespace / control chars are rejected by validate_agent_id.
        let err = reown(&conn, "claim-ns", "bad id\n", false, false).unwrap_err();
        assert!(format!("{err}").contains("agent_id"), "got: {err}");
        // No write happened.
        assert_eq!(agent_id_of(&conn, &owned).as_deref(), Some("alice"));
    }

